import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const h=JSON.parse('{"title":"JARVIS-VLA: Post-Training Large-Scale Vision Language Models to Play Visual Games with Keyboards and Mouse","description":"","frontmatter":{"title":"JARVIS-VLA: Post-Training Large-Scale Vision Language Models to Play Visual Games with Keyboards and Mouse","arxiv":"2503.16365","date":"2025-03-20","authors":"Muyao Li, Zihao Wang, Kaichen He, Xiaojian Ma, Yitao Liang","categories":"cs.CV, cs.AI","topics":"视觉-语言-动作模型, 开放世界智能体, 后训练范式","outline":[2,2]},"headers":[],"relativePath":"papers/2503.16365.md","filePath":"papers/2503.16365.md","lastUpdated":null}'),e={name:"papers/2503.16365.md"};function l(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="jarvis-vla-post-training-large-scale-vision-language-models-to-play-visual-games-with-keyboards-and-mouse" tabindex="-1">JARVIS-VLA: Post-Training Large-Scale Vision Language Models to Play Visual Games with Keyboards and Mouse <a class="header-anchor" href="#jarvis-vla-post-training-large-scale-vision-language-models-to-play-visual-games-with-keyboards-and-mouse" aria-label="Permalink to &quot;JARVIS-VLA: Post-Training Large-Scale Vision Language Models to Play Visual Games with Keyboards and Mouse&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2503.16365" target="_blank" rel="noreferrer">2503.16365</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-03-20</td></tr><tr><td><strong>作者</strong></td><td>Muyao Li, Zihao Wang, Kaichen He, Xiaojian Ma, Yitao Liang</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.AI</td></tr><tr><td><strong>一句话</strong></td><td>在动作后训练之前先插入两阶段&quot;非轨迹&quot;视觉-语言后训练（Minecraft 世界知识 → 图文对齐与空间 grounding），把 VLM 本身的能力补齐后再做模仿学习，使同一个 Qwen2-VL 骨干在 Minecraft 上千种原子任务上的成功率大幅超过直接做动作后训练。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/embodied-ai-general">通用具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本与命名说明</p><p>abs 页给出的 HTML 版本是 <strong>v2</strong>（2025-09-12 修订，v1 为 2025-03-20），本文按 v2 抓取；论文被 ACL 2025 接收。本站论文索引里该条目记作&quot;游戏中的具身体&quot;，是主题描述而非编号错误；论文自身的方法名是 <strong>ActVLP</strong>（训练范式），JARVIS-VLA 是按该范式训出的模型。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>VLA 这条线的默认做法是：拿一个在互联网数据上预训练好的 VLM，直接在大规模带动作标签的轨迹上做模仿学习。RT-2、OpenVLA 都是这个套路。这里有一个从未被认真检验的隐含前提——预训练 VLM 对下游环境的理解已经&quot;够用&quot;，剩下要学的只是动作映射。</p><p>这篇论文对这个前提提出质疑，并把质疑变成了一个具体的训练范式：在动作后训练之前，先用<strong>与环境相关但不含动作</strong>的视觉-语言任务把 VLM 本身补一遍。选 Minecraft 作为战场有其道理：它同时包含 3D 环境里的识别与导航（挖矿、杀怪）和 2D GUI 里的精确点击（合成、熔炼），后者对空间 grounding 的要求极高，而这恰恰是通用 VLM 的弱项。更重要的是 Minecraft 有 VPT 留下的大规模人类轨迹与一套成熟基准（MCU），可以做公平比较。</p><p>问题的价值在于它把&quot;数据&quot;这个词拆开了。轨迹数据昂贵且难扩展；而 wiki 文本、截图 caption、物体定位标注这类数据几乎是免费的。如果后者能换来前者的效果，VLA 的成本结构就变了。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>Minecraft 侧的前作有清晰的谱系。VPT 用 7 万小时 YouTube 视频加 IDM 伪标签做行为克隆，是&quot;纯模仿学习 + 规模&quot;的极致，但它只吃视觉、不吃语言，指令跟随需要额外套壳。STEVE-1 把 VPT 与 MineCLIP 缝起来得到文本条件策略；GROOT 用视频提示替代文本；MineDreamer 用 VLM 加扩散模型给 STEVE-1 生成中间目标。这些方法的共同上限是骨干——它们全部建立在 VPT 的 248M 模型与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 观测之上，对 GUI 里的小图标基本无能为力，所以合成与熔炼类任务的成绩一直很差。</p><p>VLA 侧的前作（OpenVLA、RT-2）确实换了大骨干，但训练配方仍然是&quot;预训练 VLM + 轨迹模仿学习&quot;一步到位。RT-2 提出过 co-fine-tuning（把 VL 数据与轨迹数据混在一起训），本文把它当作对照组之一。论文指出的缺口是：没有人系统研究过<strong>把 VL 后训练与动作后训练分成两个阶段</strong>是否比混合训练更好，也没有人量化过非轨迹数据规模与下游成功率的关系。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从已有事实推：VPT 的论文自己说过，从带动作标签的轨迹里学世界知识是低效的——因为轨迹的监督信号是&quot;下一个动作&quot;，而&quot;下界石需要用钻石镐挖&quot;这种知识只能通过大量试错间接渗透进去。与此同时，这条知识在 Minecraft wiki 里是一句白话。</p><p>第二步观察：VLM 的预训练目标（next-token prediction）与 VLA 的模仿学习目标（预测动作 token）在数学上是同一个损失，差别只在 token 的语义。既然形式一致，就没有理由把&quot;补 VLM 能力&quot;与&quot;学动作&quot;当成两种训练——它们可以是同一条流水线的两个阶段。</p><p>第三步：那么就需要把 Minecraft 的知识做成 next-token prediction 的形式。文本侧是 wiki 与问答；视觉侧是截图 caption 与 VQA；最关键的是空间 grounding（&quot;铁镐在物品栏的哪个格子&quot;），因为 GUI 操作的本质就是把语义映射到屏幕坐标。第四步：动作也要变成 token。RT-2 的做法是征用词表里最少用的 token；鼠标位移是连续量，沿用 VPT 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>-law 离散化即可。至此三个阶段的分工自然浮现。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>模仿学习的损失只惩罚&quot;下一个动作预测错了&quot;，它没有任何通道去告诉模型&quot;你根本没看清屏幕上那个格子里是什么&quot;。而这两件事在同一个 token 空间里，用同一个损失就能训。于是把便宜的、非轨迹的视觉-语言监督放在前面单独训一遍，等模型真的看得清、认得出、指得准之后，再让它学怎么动手。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以&quot;熔炼铁锭&quot;为例。观测是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">644</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">364</span></span></span></span> 的游戏画面（VPT 只有 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span>），架构是 LLaVA 式的 ViT + 两层 MLP 投影 + 自回归语言模型；与 OpenVLA 的关键差别是<strong>非马尔可夫</strong>——把历史观测图像一起放进 prompt，因为 Minecraft 是部分可观测的。</p><p>三个阶段依次是：Stage I 冻结视觉侧，只用文本世界知识数据（约 277K 条）训语言主干；Stage II 全解冻，用 caption、VQA 与空间 grounding 数据训（图文对齐 35K 个关键帧，空间 grounding 超过 404K 条），两阶段都是标准的下一 token 预测 SFT；Stage III 冻结视觉模块，扩充词表加入动作 token，在轨迹数据上做模仿学习，语言主干全参微调。</p><p>动作侧的细节有一处<strong>内部不一致</strong>需要指出：§2.1 说征用词表里最少用的 51 个 token（22 个给鼠标、29 个给键盘），而附录 A 说的是&quot;在原词表之外新增保留 token&quot;，且鼠标沿用 VPT 的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>-law 把 X、Y 各离散成 21 个 bin，共 <strong>42 个 token</strong>。42 与 22 对不上，&quot;征用旧 token&quot;与&quot;扩充词表&quot;也互相矛盾。推理时先输出按键/点击，再输出 Pitch 与 Yaw。</p><p>数据规模：轨迹侧超过 740 万帧，含 OpenAI contractor 数据、VPT 与 JARVIS-1 的 300 万条 rollout 帧，以及为 GUI 类任务合成的 640 万条专家数据；每个 MCU 任务留出 100 条以上轨迹做最终微调，其余约 100 亿 token 用于动作后训练。训练用 32 张 A800，VL 后训练约 128 GPU 小时，动作后训练约 512 GPU 小时。部署侧的描述同样自相矛盾：§3.1 写&quot;推理跑在单张 RTX 3090&quot;，附录 C 写&quot;通常部署在四张 A800&quot;。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>两个阶段的损失形式上完全一致。VL 后训练是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">SFT</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3277em;vertical-align:-1.2777em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.8723em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.2777em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathcal" style="margin-right:0.0822em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0822em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">v</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ins</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">i</span><span class="mbin mtight">−</span><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span></span></span></span></span></p><p>动作后训练是</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathcal">L</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">IL</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:2.3em;vertical-align:-1.25em;"></span><span class="mord">−</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.05em;"><span style="top:-1.9em;margin-left:0em;"><span class="pstrut" style="height:3.05em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.05em;"><span class="pstrut" style="height:3.05em;"></span><span><span class="mop op-symbol large-op">∑</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.25em;"><span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop">lo<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord"><span class="mord mathnormal">a</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mrel mtight">:</span><span class="mord mathnormal mtight">t</span><span class="mbin mtight">+</span><span class="mord mathnormal mtight" style="margin-right:0.1132em;">τ</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">o</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3175em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">ins</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mord">.</span></span></span></span></span></p><p>把动作 token 视作词表的一部分，第二式就是第一式在动作 token 上的特例。这个观察本身就是 ActVLP 能成立的形式基础：所谓&quot;后训练&quot;不是加了一个辅助损失，而是同一个损失作用在不同的 token 分布上。</p><p>由此可以推出一个论文没点明但很重要的推论（属基于证据的推断）：既然目标函数相同，把两类数据混在一起一次训完（RT-2 式 co-fine-tuning）在理论上至多是中性的。而表 2 显示混合训练不仅没有中性，反而<strong>崩到比不做任何后训练还差</strong>（合成钻石剑 0.10 vs 原始 Qwen2-VL 的 0.53）。这说明差异不来自信息量，而来自优化动力学——新增的动作 token 嵌入是随机初始化的，在同一个 batch 里与视觉-语言目标竞争梯度，很可能把视觉编码器往动作预测的捷径上拉。</p><p>鼠标侧的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">μ</span></span></span></span>-law 离散化也值得一句：它在零附近分辨率高、在大幅度处分辨率低，恰好匹配鼠标位移的重尾分布——玩家绝大多数时间在做微调瞄准，偶尔大幅转身。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>问题一：ActVLP 相对直接做动作后训练值多少？表 1 在 MCU 的四类任务（挖方块、杀实体、合成、熔炼）上给出组均值。JARVIS-VLA-Qwen2-VL 为 0.88 / 0.95 / 0.77 / 0.70；只做动作后训练的 Qwen2-VL (IL) 为 0.75 / 0.86 / 0.65 / 0.29；直接微调的 Qwen2-VL (raw) 为 0.79 / 0.84 / 0.60 / 0.07。差距最大的是熔炼组（0.70 vs 0.29 vs 0.07）。论文称领先 IL 版本&quot;超过 15%&quot;且只用了 21% 的轨迹数据——按四组均值算是 0.825 vs 0.6375，即 18.75 个百分点，口径是绝对点差而非相对提升。</p><p>有一处论文没提但值得注意：挖方块组上 <strong>raw（0.79）反而高于 IL（0.75）</strong>，也就是说大规模跨任务动作后训练在这一类上是负迁移。</p><p>问题二：分阶段是否必要？表 2 的一阶段共训对照给出了明确答案——不仅无益而且有害（合成钻石剑 0.53→0.10）。这是全文最有信息量的一个消融。</p><p>问题三：哪一类非轨迹数据最有用？图 4 的答案是空间 grounding 提升最大，其次是世界知识。图 6 进一步给出跨检查点的规律：后训练在非轨迹数据上的 eval loss 与下游成功率近似线性负相关。</p><p>问题四：scaling 行为。图 5 显示增加下游微调轨迹能提高成功率，但存在阈值——这里出现了另一处<strong>数字不一致</strong>：正文写&quot;eval loss 低于 0.30 才会出现非零成功率&quot;，而图 5 的图注写的是 0.22。</p><p>附录 C 的 chunk 消融（Qwen2-VL-2B 上做）也值得记：APT/FT/推理三档 chunk 为 1/3/2 时成功率 0.67、15 FPS；改成 1/3/3 骤降到 0.20；把 APT 阶段就用 chunk 3 则崩到 0.03。主表为公平比较统一用推理 chunk = 1（0.53 那一档）。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p>五句话版：论文提出 ActVLP，把 VLA 训练拆成&quot;文本世界知识 SFT → 多模态对齐与空间 grounding SFT → 轨迹模仿学习&quot;三个顺序阶段。据此训出的 JARVIS-VLA 是首个能在 Minecraft 上跟随人类指令完成 1000 多种原子任务的 VLA。在 MCU 四类任务上，它相对只做动作后训练的同骨干模型平均高约 19 个百分点，而只用了 21% 的轨迹数据。消融显示空间 grounding 数据贡献最大，且非轨迹数据上的 eval loss 与下游成功率近似线性相关。把三个阶段合并成一次共训会导致严重退化，说明顺序本身是关键。</p><p>三句话版：模仿学习的损失无法告诉模型&quot;你没看清屏幕&quot;，所以先用便宜的非轨迹视觉-语言数据把 VLM 的识别与定位能力补齐，再学动作。这在 Minecraft 的 GUI 类任务上带来数倍提升，且分阶段明显优于混合共训。但大部分绝对优势也可能来自骨干与分辨率的更换，论文自己承认了这一点。</p><p>一句话版：VLA 的瓶颈可能不在动作数据的量，而在骨干模型压根没看懂环境；补这一课比堆轨迹便宜得多。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>非轨迹视觉-语言数据里包含轨迹数据中不存在的信息</strong>。整套论述建立在&quot;从带动作标签的轨迹里学世界知识本身就困难&quot;之上。但注意，空间 grounding 的 404K 条标注是<strong>从 Minecraft 观测上生成的</strong>——而这些观测恰恰也出现在轨迹数据里。也就是说信息可能一直都在，只是模仿学习的目标函数不去提取它。</p><p>这个区分很关键。如果是&quot;信息不存在&quot;，那么结论是关于数据的，非轨迹语料不可替代；如果是&quot;信息存在但优化不出来&quot;，那么结论是关于课程与优化的，原则上可以通过改损失（比如在轨迹训练中加辅助的 grounding 头）达到同样效果，而不需要单独造语料。</p><p>论文自己的表 2 恰恰支持后一种解读：同样的数据，混在一起训会崩，分阶段训则大涨。数据集合完全相同，差异只在顺序——这是&quot;优化现象&quot;而非&quot;信息现象&quot;的直接证据。论文缺的对照是：在 Stage III 里保留一个 grounding 辅助损失（而不是完全冻结视觉、只训动作 token），看能否用一个阶段达到三阶段的效果。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周内可做的判决实验针对&quot;分辨率混淆&quot;。取 Qwen2-VL-7B，不做任何 VL 后训练，只在 MCU 任务上微调，跑两个配置：观测分辨率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">644</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">364</span></span></span></span>（论文配置）与下采样到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span>（VPT 配置），其余完全相同。分别在四类任务上评测，每任务 30 次。</p><ul><li>若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 档在合成/熔炼上崩到接近 VPT-BC 的水平（0.41 / 0.05），说明 raw Qwen2-VL 相对经典 Minecraft 智能体的优势主要是分辨率带来的，与&quot;用了大 VLM&quot;关系不大。</li><li>若两档差距不大，则支持论文归因于骨干能力。</li></ul><p>第二个便宜实验：只用空间 grounding 数据做 ActVLP，分别在 GUI 类（合成/熔炼）与 3D 类（挖矿/杀怪）任务上评测。若 grounding 的收益几乎全部落在 GUI 类，说明它起的是&quot;点击位置监督&quot;的作用，而非通用空间理解。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者一侧，最有力的攻击是：<strong>表 1 里相对经典 Minecraft 智能体的巨大领先，几乎全部可以由骨干规模与观测分辨率解释，与 ActVLP 无关。</strong></p><p>证据就在论文里。未经任何后训练的 Qwen2-VL (raw) 已经在四组中的三组超过 VPT-BC、VPT-RL、STEVE-1、GROOT 与 MineDreamer；作者自己也承认合成类的提升&quot;主要归因于 VLM 里的 ViT 与高分辨率处理&quot;。而所有基线都跑在 248M 参数、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">128</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">128</span></span></span></span> 观测上。因此摘要里&quot;相对最好的智能体基线提升 40%&quot;这个说法，度量的是 7B 大模型 + 5 倍分辨率的组合效应，ActVLP 的净贡献只能由 JARVIS-VLA 与 Qwen2-VL (IL) / (raw) 的差值给出，即约 19 与 21 个百分点。</p><p>第二个替代解释针对熔炼组的 0.07 → 0.70。合成与熔炼是纯 GUI 任务：状态是一张固定布局的物品栏截图，正确动作是点击某个格子。而空间 grounding 数据训的正是&quot;给定物品名输出屏幕坐标&quot;。这意味着所谓&quot;非轨迹数据&quot;对 GUI 任务而言几乎是<strong>动作监督的另一种写法</strong>，并不真正 off-trajectory。判决实验：把 grounding 数据里所有与物品栏格子相关的样本剔除，只保留 3D 场景中的物体定位，重训 Stage II。若熔炼组的增益大幅缩水，则&quot;off-trajectory 数据带来通用能力&quot;这一叙述需要改写为&quot;grounding 数据是 GUI 动作的等价监督&quot;。</p><p>第三点是评测协议：每任务至少 30 次试验，成功率刻度约 0.033；组均值由 5 个以上任务合成，但论文未报告任何置信区间或多次运行的方差，0.03–0.05 量级的差异（比如 raw 0.79 vs IL 0.75）无法与噪声区分。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p>论文最有价值但被自己低估的发现是图 6：<strong>非轨迹数据上的 eval loss 与下游任务成功率近似线性相关</strong>。这意味着智能体评测——通常要跑几十次 rollout、极其昂贵——可以被一个离线的、几秒钟就能算完的 loss 代理。</p><p>(a) 驱动这个想法的局限：现在的三阶段配方是固定的、手工设计的，数据配比靠试。而作者已经证明存在一个廉价的可预测量，却只把它当作 scaling 曲线的横轴，没有拿来做数据选择。</p><p>(b) 可借鉴的相邻工具：LLM 预训练里的数据估值方法（datamodels、influence functions、DSIR 式的分布匹配）。它们的共同前提正是&quot;下游表现可由某个可微/可算的代理预测&quot;，而图 6 给出了这个前提在具身场景下的经验支持。把探针集设计成一小批带真值的 grounding/知识题，就能对任意候选语料估计其边际下游价值，从而自动决定 Stage I/II 的数据配比，而不是把三类数据平均混。</p><p>(c) 第一个实验：先检验这个线性关系是否跨任务族成立。用挖矿与杀怪两组任务拟合 loss→成功率的回归，去预测合成与熔炼两组；再反过来做一次。如果跨族预测失效（很可能，因为 GUI 与 3D 导航依赖的能力完全不同），那么正确的做法就不是一个全局 loss，而是<strong>按能力维度分解的多个探针 loss</strong>——这本身就是一个新的框架：把&quot;该给智能体补什么课&quot;变成一个可测量、可优化的诊断问题，而不是靠直觉配数据。</p>',59)])])}const u=a(e,[["render",l]]);export{h as __pageData,u as default};
